<?php
/** School Services 4.9.0 — shared tenant, transaction, invoice and presentation helpers. */
if(!defined('SCHOOLOS_SERVICES_LIBRARY')){header('Location: index.php?s=services');exit;}
function sv_schema():array{return ["CREATE TABLE IF NOT EXISTS sv_settings(tenant_id BIGINT UNSIGNED NOT NULL,setting_key VARCHAR(50) NOT NULL,cipher TEXT NOT NULL,PRIMARY KEY(tenant_id,setting_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4", "CREATE TABLE IF NOT EXISTS sv_roles(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,capability VARCHAR(30) NOT NULL,PRIMARY KEY(tenant_id,user_id,capability)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"] ;}
function sv_tables():array{return ['sv_roles','sv_settings','lib_meta','lib_reservations','lib_charges','lib_alerts','lib_resources','lib_access','iv_items','iv_moves','iv_suppliers','iv_requests','iv_orders','iv_order_lines','iv_receipts','iv_store_orders','iv_asset_meta','iv_asset_events','iv_audits','eg_contacts','eg_consents','eg_templates','eg_campaigns','eg_deliveries','eg_wallets','eg_credit_log','eg_votes','eg_push','wc_sites','wc_domains','wc_content','wc_enquiries','wc_tours'];}
function sv_ready(bool $refresh=false):bool{static $cached=null;if($refresh)$cached=null;if($cached!==null)return $cached;foreach(sv_tables() as $t)if(!op_has($t))return $cached=false;return $cached=true;}
function sv_install():void{global $pdo;lp_install();op_install();cmInstall();crmInstall();fn45Install();foreach(array_merge(sv_schema(),lib_schema(),iv_schema(),eg_schema(),wc_schema()) as $sql)$pdo->exec($sql);sv_ready(true);}
function sv_secret_key():string{$dir=__DIR__.'/storage/system';if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))throw new RuntimeException('Private storage unavailable.');if(is_link($dir)||is_link($dir.'/services-key.php'))throw new RuntimeException('Private key path unavailable.');$lock=fopen($dir.'/services-key.lock','c');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('Private key lock unavailable.');try{chmod($dir.'/services-key.lock',0600);$file=$dir.'/services-key.php';if(!is_file($file)){if(op_has('sv_settings')&&(int)g('SELECT COUNT(*) FROM sv_settings')>0)throw new RuntimeException('Private credential key missing. Restore its matching backup before accessing saved settings.');$body='<?php return '.var_export(base64_encode(random_bytes(32)),true).';';$f=fopen($file,'x');if(!$f)throw new RuntimeException('Private key creation failed.');try{if(!chmod($file,0600)||fwrite($f,$body)!==strlen($body)||!fflush($f))throw new RuntimeException('Private key write failed.');}finally{fclose($f);}}$key=base64_decode(require $file,true);if(!is_string($key)||strlen($key)!==32)throw new RuntimeException('Private key is invalid. Restore its backup; do not regenerate it over existing credentials.');return $key;}finally{flock($lock,LOCK_UN);fclose($lock);}}
function sv_save_secret(int $tid,string $name,string $value):void{$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($value,'aes-256-gcm',sv_secret_key(),OPENSSL_RAW_DATA,$iv,$tag);if($cipher===false)throw new RuntimeException('Credential encryption failed.');q('INSERT INTO sv_settings VALUES(?,?,?) ON DUPLICATE KEY UPDATE cipher=VALUES(cipher)',[$tid,$name,base64_encode($iv.$tag.$cipher)]);}
function sv_secrets(int $tid):array{if(!op_has('sv_settings'))return [];$rows=q('SELECT * FROM sv_settings WHERE tenant_id=?',[$tid])->fetchAll();if(!$rows)return [];$key=sv_secret_key();$out=[];foreach($rows as $r){$raw=base64_decode($r['cipher'],true);if($raw===false||strlen($raw)<29)throw new RuntimeException('Stored provider credential is invalid.');$value=openssl_decrypt(substr($raw,28),'aes-256-gcm',$key,OPENSSL_RAW_DATA,substr($raw,0,12),substr($raw,12,16));if($value===false)throw new RuntimeException('Provider credential could not be decrypted. Restore the matching private key.');$out[$r['setting_key']]=$value;}return $out;}
function sv_can(array $u,string $cap):bool{return $u['role']==='school_admin'||(in_array($u['role'],['staff','teacher'],true)&&op_has('sv_roles')&&(bool)g('SELECT user_id FROM sv_roles WHERE tenant_id=? AND user_id=? AND capability=?',[$u['tenant_id'],$u['id'],$cap]));}
function sv_need(array $u,string $cap):void{if(!sv_can($u,$cap))throw new RuntimeException('Requires '.$cap.' access.');}
function sv_own(string $table,array $u,int $id,bool $lock=false):array{if(!in_array($table,array_merge(sv_tables(),['books','inventory','assets','students','users','classes','lp_library_loans','fn_invoices','staff']),true))throw new LogicException('Invalid internal table.');$r=q("SELECT * FROM `$table` WHERE tenant_id=? AND id=?".($lock?' FOR UPDATE':''),[$u['tenant_id'],$id])->fetch();if(!$r)throw new RuntimeException('Record unavailable.');return $r;}
function sv_tx(callable $f):mixed{global $pdo;$pdo->beginTransaction();try{$v=$f();$pdo->commit();return $v;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function sv_enum(string $key,array $allowed):string{$v=op_text($key,40,true);if(!in_array($v,$allowed,true))throw new RuntimeException('Invalid '.$key.'.');return $v;}
function sv_qty(string $key,int $max=1000000,bool $zero=false):int{$v=op_id($key);if($v<($zero?0:1)||$v>$max)throw new RuntimeException('Check '.$key.'.');return $v;}
function sv_https(string $v):string{$p=parse_url($v);if(!$p||($p['scheme']??'')!=='https'||empty($p['host'])||isset($p['user'])||isset($p['pass'])||preg_match('/[\x00-\x20]/',$v)||filter_var($v,FILTER_VALIDATE_URL)===false)throw new RuntimeException('Use a valid HTTPS address.');return $v;}
function sv_invoice(array $u,int $sid,string $ref,int $amount,string $description):int{global $pdo;if(!$pdo->inTransaction()||$amount<1||strlen($ref)>90)throw new LogicException('Invoice requires a positive amount and transaction.');sv_own('students',$u,$sid,true);$r=q('SELECT * FROM fn_invoices WHERE tenant_id=? AND reference=?',[$u['tenant_id'],$ref])->fetch();if($r){if((int)$r['amount_kobo']!==$amount||(int)$r['student_id']!==$sid)throw new RuntimeException('Existing charge differs; review in Finance.');return (int)$r['id'];}q('INSERT INTO fn_invoices(tenant_id,student_id,reference,description,amount_kobo) VALUES(?,?,?,?,?)',[$u['tenant_id'],$sid,$ref,mb_substr($description,0,190),$amount]);$id=(int)$pdo->lastInsertId();fnJournal((int)$u['tenant_id'],'INV-'.$id,'1100','4100',$amount,'',$description);return $id;}
function sv_children(array $u):array{return op_choices(op_children($u));}
function sv_student(array $u,int $sid,string $cap):array{if(!sv_can($u,$cap))return op_child($u,$sid);return sv_own('students',$u,$sid);}
function sv_action(array $u):string{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??'')))throw new RuntimeException('Security token expired.');$a=op_text('sv_action',40,true);if($a==='activate'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');sv_install();return 'School Services activated; existing records retained.';}if(!sv_ready())throw new RuntimeException('Activate School Services first.');if($a==='grant'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');$target=sv_own('users',$u,op_id('user_id'));if(!$target['active']||!in_array($target['role'],['staff','teacher'],true))throw new RuntimeException('Choose an active staff/teacher account.');$cap=sv_enum('capability',['librarian','stock_manager','procurement_approver','asset_manager','communications_manager','website_editor','website_approver']);if(sv_enum('decision',['grant','revoke'])==='grant')q('INSERT IGNORE INTO sv_roles VALUES(?,?,?)',[$u['tenant_id'],$target['id'],$cap]);else q('DELETE FROM sv_roles WHERE tenant_id=? AND user_id=? AND capability=?',[$u['tenant_id'],$target['id'],$cap]);audit('services.access','user',$target['id'].' '.$cap);return 'School Services access updated.';}
 foreach(['lib_'=>'lib_action','iv_'=>'iv_action','eg_'=>'eg_action','wc_'=>'wc_action'] as $prefix=>$f)if(str_starts_with($a,$prefix))return $f($u,substr($a,strlen($prefix)));throw new RuntimeException('Unsupported service action.');}
function sv_form(string $action,array $fields,string $button):void{echo '<form method="post" enctype="multipart/form-data" class="op-form"><input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="sv_action" value="'.e($action).'">';foreach($fields as $key=>$spec){[$label,$type]=$spec;if(is_array($type))op_select($key,$label,$type);elseif($type==='check')op_check($key,$label);else op_field($key,$label,$type,(string)($spec[2]??''),(bool)($spec[3]??true));}op_end($button);}
function sv_tabs(string $area,array $tabs,string $default):string{$v=is_string($_GET['view']??null)?$_GET['view']:$default;if(!isset($tabs[$v]))$v=$default;echo '<nav class="sv-nav">';foreach($tabs as $key=>$label)echo '<a '.($v===$key?'aria-current="page"':'').' href="?s=services&amp;area='.$area.'&amp;view='.e($key).'">'.e($label).'</a>';echo '</nav>';return $v;}
function sv_render(array $u):void{echo '<style>.sv-hero{background:linear-gradient(115deg,#172e4b,#087e80);color:white;padding:28px;border-radius:18px}.sv-nav{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.sv-nav a{padding:11px;background:var(--card-bg);color:var(--ink);border:1px solid var(--line);border-radius:10px;text-decoration:none}.op-card{border:1px solid var(--line);background:var(--card-bg);padding:23px;border-radius:15px;margin:16px 0}.op-scroll{overflow:auto}.op-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:18px 0}.op-form label{display:grid;gap:6px}.op-form input,.op-form textarea,.op-form select{padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--field-bg);color:var(--field-text);font:inherit;width:100%}.op-form label:has(textarea){grid-column:1/-1}.op-form .op-check{display:flex;align-items:center}.op-check input{width:auto}.op-card p{overflow-wrap:anywhere;white-space:pre-wrap}@media(max-width:650px){.op-form{grid-template-columns:1fr}.op-card{padding:15px}}</style><div class="sv-hero"><h2>'.e(px_service_title($u)).'</h2><p>Useful tools and actions for your assigned school role.</p></div>';
 if(!sv_ready()){op_card('Activate School Services');echo '<p>Back up the database. Activation adds service tables and retains existing loans, stock, assets, communications and portal records.</p>';if($u['role']==='school_admin')sv_form('activate',[],'Activate School Services');else echo '<p>Ask your school administrator to activate these modules.</p>';echo '</section>';return;}
 $area=is_string($_GET['area']??null)?$_GET['area']:px_default_service($u);if(!px_service_area($u,$area))throw new RuntimeException('This service is not assigned to your role.');echo '<nav class="sv-nav">';foreach(['library'=>'Library','inventory'=>'Inventory, Procurement & Assets','engagement'=>'Communications & Engagement','website'=>'Website & CMS','access'=>'Access controls'] as $k=>$v){if(!px_service_area($u,$k))continue;if(in_array($k,['website','access'],true)&&($k==='access'?$u['role']!=='school_admin':!sv_can($u,'website_editor')&&!sv_can($u,'website_approver')))continue;echo '<a href="?s=services&amp;area='.$k.'">'.e($v).'</a>';}echo '</nav>';
 if($area==='access'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required.');op_card('Assign scoped service access');$caps=['librarian','stock_manager','procurement_approver','asset_manager','communications_manager','website_editor','website_approver'];sv_form('grant',['user_id'=>['Active employee account',op_choices(q("SELECT id,name FROM users WHERE tenant_id=? AND active=1 AND role IN ('teacher','staff')",[$u['tenant_id']])->fetchAll())],'capability'=>['Access',array_combine($caps,$caps)],'decision'=>['Decision',['grant'=>'Grant','revoke'=>'Revoke']]],'Save access');op_table(q('SELECT u.name,r.capability FROM sv_roles r JOIN users u ON u.id=r.user_id AND u.tenant_id=r.tenant_id WHERE r.tenant_id=?',[$u['tenant_id']])->fetchAll(),['Account','Access']);echo '</section>';}
 elseif($area==='inventory')iv_render($u);elseif($area==='engagement')eg_render($u);elseif($area==='website')wc_render($u);else lib_render($u);
}
